export interface Graph {
  [node: string]: { [neighbor: string]: number }
}

export interface DijkstraResult {
  distances: Record<string, number>
  previous: Record<string, string | null>
  path: (target: string) => string[]
}

/**
 * Finds shortest paths from startNode to all other reachable nodes using Dijkstra's algorithm.
 * - Throw Error if any edge weight is negative.
 * - Handle disconnected nodes (distance = Infinity).
 * - Return path function: returns [] if unreachable, [startNode] if startNode === target.
 */
export function dijkstra(graph: Graph, startNode: string): DijkstraResult {
  // Throw an Error if any edge weight is negative.
  for (const node of Object.keys(graph)) {
    for (const neighbor of Object.keys(graph[node])) {
      if (graph[node][neighbor] < 0) {
        throw new Error(
          `Edge weight from "${node}" to "${neighbor}" is negative: ${graph[node][neighbor]}`
        )
      }
    }
  }

  // Collect every node: graph keys plus any neighbor referenced in an edge.
  const nodes = new Set<string>()
  for (const node of Object.keys(graph)) {
    nodes.add(node)
    for (const neighbor of Object.keys(graph[node])) {
      nodes.add(neighbor)
    }
  }
  nodes.add(startNode)

  // Initialize distances and previous pointers.
  const distances: Record<string, number> = {}
  const previous: Record<string, string | null> = {}
  const unvisited = new Set<string>()

  for (const node of nodes) {
    distances[node] = Infinity
    previous[node] = null
    unvisited.add(node)
  }
  distances[startNode] = 0

  while (unvisited.size > 0) {
    // Pick the unvisited node with the smallest tentative distance.
    let current: string | null = null
    let smallest = Infinity
    for (const node of unvisited) {
      if (distances[node] < smallest) {
        smallest = distances[node]
        current = node
      }
    }

    // Remaining nodes are unreachable from startNode.
    if (current === null || smallest === Infinity) break

    unvisited.delete(current)

    const neighbors = graph[current] ?? {}
    for (const neighbor of Object.keys(neighbors)) {
      const alt = distances[current] + neighbors[neighbor]
      if (alt < distances[neighbor]) {
        distances[neighbor] = alt
        previous[neighbor] = current
      }
    }
  }

  const path = (target: string): string[] => {
    if (target === startNode) return [startNode]
    if (!(target in distances) || distances[target] === Infinity) return []

    const result: string[] = []
    const seen = new Set<string>()
    let current: string | null = target

    while (current !== null && !seen.has(current)) {
      seen.add(current)
      result.unshift(current)
      if (current === startNode) break
      current = previous[current]
    }

    return result[0] === startNode ? result : []
  }

  return { distances, previous, path }
}
